per_case_results.actual_sql:
SELECT "ID", EXTRACT(YEAR FROM AGE(CURRENT_TIMESTAMP, "Birthday")) AS "age"
FROM "patient"
WHERE "RVVT" = '+';

SELECT "ID", "sex", "birthday"
FROM "patient"
WHERE "UN" = 29;

SELECT AVG(EXTRACT(YEAR FROM AGE(CURRENT_DATE, "birthday"))) AS average_age
FROM "patient"
WHERE "sex" = 'M' AND "T-CHO" >= 250;

SELECT COUNT(DISTINCT "patient_id") 
FROM "lab_results" 
WHERE "igg" >= 2000;
